			'unicode' => ['{"name":"Café Crème 日本語"}', '{"name":"Café Crème 日本語"}', 'sha256=8828459bb4f050a0ae4d633d71edefa6027c1cc39933e8b27de9bc5fafd491ac'],
			'unsorted' => ['{"b":2,"a":1,"c":3}', '{"a":1,"b":2,"c":3}', 'sha256=cefa417c919e24dadad16670fb997f379aece68be25f46d70bd2ee6541bb7b0a'],
			'wholeFloats' => ['{"whole":1.0,"negWhole":-2.0,"frac":2.50}', '{"frac":2.5,"negWhole":-2,"whole":1}', 'sha256=568f803efa06262d9bc43020a326a2d335739bc54c2f1f546d2f0c4d7ac70619'],
		];
	}

	#[Test]
	#[DataProvider('referenceVectors')]
	public function it_canonicalises_identically_to_go(string $input, string $canonical, string $signature): void
	{
		$this->assertSame($canonical, WebhookVerifier::canonicalJson($input));
	}

	#[Test]
	#[DataProvider('referenceVectors')]
	public function it_signs_identically_to_go(string $input, string $canonical, string $signature): void
	{
		$this->assertSame(
			$signature,
			WebhookVerifier::computeSignature(self::SECRET, self::TIMESTAMP, $input)
		);
	}

