	#[Test]
	#[DataProvider('goldenVectors')]
	public function it_canonicalises_the_shared_golden_vectors(string $payload, string $secret, string $timestamp, string $canonical, string $signature): void
	{
		$this->assertSame($canonical, WebhookVerifier::canonicalJson($payload));
	}

	#[Test]
	#[DataProvider('goldenVectors')]
	public function it_signs_the_shared_golden_vectors(string $payload, string $secret, string $timestamp, string $canonical, string $signature): void
	{
		$this->assertSame($signature, WebhookVerifier::computeSignature($secret, $timestamp, $payload));
	}

	#[Test]
	public function it_sorts_keys_at_every_level(): void
	{
		$this->assertSame('{"a":1,"b":2}', WebhookVerifier::canonicalJson('{"b":2,"a":1}'));
		$this->assertSame('{"z":{"x":2,"y":1}}', WebhookVerifier::canonicalJson('{"z":{"y":1,"x":2}}'));
	}

	#[Test]
	public function it_preserves_array_order(): void
	{
		// Arrays are ordered by definition: sorting them would change meaning.
		$this->assertSame('{"items":[3,1,2]}', WebhookVerifier::canonicalJson('{"items":[3,1,2]}'));
	}

	#[Test]
	public function it_keeps_an_empty_object_distinct_from_an_empty_array(): void
	{
		// Decoding with assoc=true would turn {} into [] and change the signed bytes.
		$this->assertSame('{}', WebhookVerifier::canonicalJson('{}'));
		$this->assertSame('[]', WebhookVerifier::canonicalJson('[]'));
		$this->assertSame('{"a":{},"b":[]}', WebhookVerifier::canonicalJson('{"b":[],"a":{}}'));
	}

	#[Test]
	public function it_rejects_invalid_json(): void
	{
		foreach (['{not json', '', '{"a":1', '{"a":01}', "{\"a\":\"\x01\"}", '{"a":1} x', '[1,]', '{"a":1e400}'] as $bad) {
			try {
				WebhookVerifier::canonicalJson($bad);
				$this->fail('Expected ' . json_encode($bad) . ' to be rejected.');
			} catch (ValidationException $e) {
				$this->assertStringContainsString('not valid JSON', $e->getMessage());
			}
		}
	}

	#[Test]
	public function numbers_do_not_depend_on_serialize_precision(): void
	{
		$previous = ini_get('serialize_precision');

		try {
			foreach (['17', '100', '5'] as $precision) {
				ini_set('serialize_precision', $precision);

				$this->assertSame('{"fee":0.1,"price":19.99,"tiny":1e-7}', WebhookVerifier::canonicalJson('{"price":19.99,"fee":0.1,"tiny":1e-7}'));
				$this->assertSame('{"n":0.3}', WebhookVerifier::canonicalJson(['n' => 0.3]));
				$this->assertSame($precision, ini_get('serialize_precision'), 'The setting is restored.');
			}
		} finally {
			ini_set('serialize_precision', (string) $previous);
		}
	}

	#[Test]
	public function strings_follow_go_decoding_rules(): void
	{
		// A high surrogate followed by a non-surrogate escape: U+FFFD, then the next escape.
		$this->assertSame("{\"s\":\"\u{FFFD}A\"}", WebhookVerifier::canonicalJson('{"s":"\ud800\u0041"}'));
		// A valid pair is one character.
		$this->assertSame("{\"s\":\"\u{10000}\"}", WebhookVerifier::canonicalJson('{"s":"\ud800\udc00"}'));
		// Invalid UTF-8 bytes become U+FFFD, one per byte, as Go's decoder does.
		$this->assertSame("{\"s\":\"a\u{FFFD}\u{FFFD}b\"}", WebhookVerifier::canonicalJson("{\"s\":\"a\xE2\x82b\"}"));
		// Duplicate keys: last wins, as in a Go map.
		$this->assertSame('{"a":2}', WebhookVerifier::canonicalJson('{"a":1,"a":2}'));
		// Escaped slashes and whitespace-heavy input canonicalise away.
		$this->assertSame('{"u":"a/b"}', WebhookVerifier::canonicalJson(" { \"u\" :\r\n \"a\\/b\" } "));
	}

	#[Test]
	public function a_decoded_payload_canonicalises_like_the_raw_body(): void
	{
		$raw = '{"b":{},"a":[],"n":-0.0,"big":"1000000000000000000","f":19.99}';

		$this->assertSame(
			WebhookVerifier::canonicalJson($raw),
			WebhookVerifier::canonicalJson(json_decode($raw, false)),
			'Decoding objects as stdClass keeps {} apart from [].',
		);

		// An associative decode cannot tell {} from []; that one ambiguity is documented.
		$this->assertSame(
			'{"a":[],"b":[],"big":"1000000000000000000","f":19.99,"n":-0}',
			WebhookVerifier::canonicalJson(json_decode($raw, true)),
		);
	}

	#[Test]
	public function it_accepts_a_genuine_webhook(): void
	{
		$ts = (string) time();
		$payload = '{"uuid":"pay@abc","txType":"payment"}';
		$sig = WebhookVerifier::computeSignature(self::SECRET, $ts, $payload);

		WebhookVerifier::verify(self::SECRET, $ts, $sig, $payload);
		$this->addToAssertionCount(1);
	}

	#[Test]
	public function it_accepts_a_payload_whose_keys_were_reordered(): void
	{
		$ts = (string) time();
		$sig = WebhookVerifier::computeSignature(self::SECRET, $ts, '{"a":1,"b":2}');

		WebhookVerifier::verify(self::SECRET, $ts, $sig, '{"b":2,"a":1}');
		$this->addToAssertionCount(1);
	}

	#[Test]
	public function it_rejects_a_tampered_payload(): void
	{
		$ts = (string) time();
		$sig = WebhookVerifier::computeSignature(self::SECRET, $ts, '{"uuid":"pay@abc"}');

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('signature mismatch');
		WebhookVerifier::verify(self::SECRET, $ts, $sig, '{"uuid":"pay@EVIL"}');
	}

	#[Test]
	public function it_rejects_a_tampered_timestamp(): void
	{
		$ts = time();
		$sig = WebhookVerifier::computeSignature(self::SECRET, (string) $ts, '{"a":1}');

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('signature mismatch');
		WebhookVerifier::verify(self::SECRET, (string) ($ts - 30), $sig, '{"a":1}');
	}

	#[Test]
	public function it_rejects_the_wrong_secret(): void
	{
		$ts = (string) time();
		$sig = WebhookVerifier::computeSignature(self::SECRET, $ts, '{"a":1}');

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('signature mismatch');
		WebhookVerifier::verify('whsec_wrong', $ts, $sig, '{"a":1}');
	}

	#[Test]
	public function it_rejects_a_replayed_webhook(): void
	{
		$old = (string) (time() - 600);
		$sig = WebhookVerifier::computeSignature(self::SECRET, $old, '{"a":1}');

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('expired');
		WebhookVerifier::verify(self::SECRET, $old, $sig, '{"a":1}');
	}

	#[Test]
	public function it_rejects_a_future_timestamp(): void
	{
		// Guards against a forged future timestamp extending the replay window.
		$future = (string) (time() + 600);
		$sig = WebhookVerifier::computeSignature(self::SECRET, $future, '{"a":1}');

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('expired');
		WebhookVerifier::verify(self::SECRET, $future, $sig, '{"a":1}');
	}

	#[Test]
	public function it_honours_a_custom_replay_window(): void
	{
		$old = (string) (time() - 600);
		$sig = WebhookVerifier::computeSignature(self::SECRET, $old, '{"a":1}');

		WebhookVerifier::verify(self::SECRET, $old, $sig, '{"a":1}', 1800);
		$this->addToAssertionCount(1);
	}

	#[Test]
	public function it_rejects_a_non_numeric_timestamp(): void
	{
		// Parsed like Go's strconv.ParseInt: no whitespace, no decimals, within int64.
		foreach (['nope', ' 1700000000', '1700000000 ', '1.7e9', '0x10', '99999999999999999999', '-9223372036854775809'] as $bad) {
			try {
				WebhookVerifier::verify(self::SECRET, $bad, 'sha256=abc', '{"a":1}', nowSeconds: 1700000000);
				$this->fail("Expected {$bad} to be rejected.");
			} catch (ValidationException $e) {
				$this->assertSame('webhook timestamp is not a unix-seconds integer', $e->getMessage());
			}
		}
	}

	#[Test]
	public function a_signed_timestamp_is_accepted_like_go(): void
	{
		$timestamp = '+1700000000';
		$signature = WebhookVerifier::computeSignature(self::SECRET, $timestamp, '{"a":1}');

		WebhookVerifier::verify(self::SECRET, $timestamp, $signature, '{"a":1}', nowSeconds: 1700000100);
		$this->addToAssertionCount(1);
	}

	#[Test]
	public function a_non_positive_max_age_means_the_default_window(): void
	{
		$timestamp = '1700000000';
		$signature = WebhookVerifier::computeSignature(self::SECRET, $timestamp, '{"a":1}');

		// 200 s old: inside the default 300 s window, even with maxAge 0 or -1.
		WebhookVerifier::verify(self::SECRET, $timestamp, $signature, '{"a":1}', 0, 1700000200);
		WebhookVerifier::verify(self::SECRET, $timestamp, $signature, '{"a":1}', -1, 1700000200);

		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('expired');

		WebhookVerifier::verify(self::SECRET, $timestamp, $signature, '{"a":1}', 0, 1700000400);
	}

	#[Test]
	public function an_extreme_timestamp_is_rejected_without_overflow(): void
	{
		$this->expectException(ValidationException::class);
		$this->expectExceptionMessage('expired');

		WebhookVerifier::verify(self::SECRET, '-9223372036854775808', 'sha256=abc', '{"a":1}', nowSeconds: PHP_INT_MAX);
	}

	#[Test]
	public function it_extracts_headers_from_a_server_superglobal(): void
	{
		// PHP mangles header names into $_SERVER as HTTP_X_WEBHOOK_*.
		$h = WebhookVerifier::extractHeaders([
			'HTTP_X_WEBHOOK_SIGNATURE_256' => 'sha256=abc',
			'HTTP_X_WEBHOOK_TIMESTAMP' => '1700000000',
			'HTTP_X_WEBHOOK_ID' => 'pay@abc',
			'REQUEST_METHOD' => 'POST',
		]);

		$this->assertSame('sha256=abc', $h['signature']);
		$this->assertSame('1700000000', $h['timestamp']);
		$this->assertSame('pay@abc', $h['webhookId']);
		$this->assertFalse($h['isTest']);
	}

	#[Test]
	public function it_extracts_headers_from_a_psr7_style_array(): void
	{
		$h = WebhookVerifier::extractHeaders([
			'X-Webhook-Signature-256' => ['sha256=abc'],
			'X-Webhook-Timestamp' => ['1700000000'],
			'X-Webhook-Id' => [WebhookVerifier::TEST_WEBHOOK_ID],
		]);

		$this->assertSame('sha256=abc', $h['signature']);
		$this->assertTrue($h['isTest']);
	}

	#[Test]
	public function missing_headers_come_back_empty(): void
	{
		$h = WebhookVerifier::extractHeaders([]);

		$this->assertSame('', $h['signature']);
		$this->assertSame('', $h['timestamp']);
		$this->assertFalse($h['isTest']);
	}
}
